const input = items[0].json;
const state = input && typeof input === 'object' ? { ...input } : {};

// Support webhook test input that wraps data under body.*
const body = state.body || {};
if (!state.payload && body.payload) state.payload = body.payload;
if (!state.agent && body.agent) state.agent = body.agent;

const fallbackIntent =
  state.intent ||
  state.request_text ||
  state.usecase ||
  state.usecase_ref ||
  state.text ||
  (state.payload && state.payload.intent) ||
  '';

if (!state.payload) {
  state.payload = {
    intent: fallbackIntent,
    input: state.input || {},
    context: state.context || (state.request_text ? { request_text: state.request_text } : {})
  };
}

if (!state.agent) {
  const detected = state.detected_usecase || state.usecase || state.usecase_ref || state.payload.intent || null;
  const mode = state.mode || (detected ? 'compile' : 'plan');
  state.agent = {
    mode,
    detected_usecase: detected
  };
}

if (!state.payload || !state.agent) {
  throw new Error('Invalid envelope: payload or agent missing');
}

const registryDefaults = {
