function normalizeUsecases(source) {
  if (!source) return {};
  let value = source;
  if (value && typeof value === 'object' && Array.isArray(value.items)) {
    value = value.items;
  }
  if (Array.isArray(value)) {
    const map = {};
    for (const item of value) {
      if (item && item.id) {
        map[item.id] = item;
      }
    }
    return map;
  }
  if (value && typeof value === 'object') {
    return value;
  }
  return {};
}

const payloadRegistry = state.payload.registry || {};
const defaultUsecases = normalizeUsecases(registryDefaults.usecases);
const payloadUsecases = normalizeUsecases(payloadRegistry.usecases);
const resolvedUsecases = Object.keys(payloadUsecases).length > 0 ? payloadUsecases : defaultUsecases;

state.registry = {
  ...registryDefaults,
  ...payloadRegistry,
  capabilities: payloadRegistry.capabilities || registryDefaults.capabilities,
  usecases: resolvedUsecases
};

state.policies = state.policies || {};
state.plan = state.plan || {};

state.plan.steps = [];
state.authorization = state.authorization || {};

return [{ json: state }];

const state = items[0].json;

const ref = state.agent.detected_usecase;
const usecase = state.registry.usecases?.[ref];

if (!usecase) {
  throw new Error(`Unknown certified usecase: ${ref}`);
}

// Validation minimale
if (usecase.inputs_required) {
  for (const key of usecase.inputs_required) {
    if (!(key in state.payload.input)) {
      throw new Error(`Missing required input: ${key}`);
    }
  }
}

function isOutputReference(value) {
  if (typeof value === 'string') {
    return /\{\{\s*\$step\[\d+\]\.outputs\./.test(value);
  }

  return false;
}

function extractStepIndex(reference) {
  const match = reference.match(/\[(\d+)\]/);
  return match ? parseInt(match[1], 10) : -1;
}

function validateInputs(stepInputs, stepIndex, allSteps) {
  if (!stepInputs || typeof stepInputs !== 'object') return;

  for (const [key, value] of Object.entries(stepInputs)) {
    if (!isOutputReference(value)) {
      continue;
    }

    const ref = typeof value === 'string' ? value : value.$ref;
    const referencedIndex = extractStepIndex(ref || '');
    if (referencedIndex < 0) {
      throw new Error(`Step ${stepIndex}, input "${key}": Invalid output reference format`);
    }
    if (referencedIndex >= allSteps.length) {
      throw new Error(`Step ${stepIndex}, input "${key}": References step ${referencedIndex} which does not exist in the plan`);
    }
    if (referencedIndex >= stepIndex) {
      throw new Error(`Step ${stepIndex}, input "${key}": References step ${referencedIndex} which is not a precedent step`);
    }
  }
}

function buildStep(step, index, allSteps) {
  const toolRef = step.tool_ref || step.ref || step.tool;
  if (!toolRef || typeof toolRef !== 'string') {
    throw new Error(`Step ${index}: tool_ref missing`);
  }

  const args = step.args || step.params || {};
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error(`Step ${index}: args must be an object`);
  }

  const outputs = step.outputs || {};
  if (outputs === null || typeof outputs !== 'object' || Array.isArray(outputs)) {
    throw new Error(`Step ${index}: outputs must be an object`);
  }

  const normalized = {
    id: `step_${index}`,
    type: 'tool',
    tool_ref: toolRef,
    args,
    inputs: args,
    outputs
  };

  validateInputs(normalized.inputs, index, allSteps);
  return normalized;
}

// Compilation deterministe
state.plan.steps = usecase.steps_template.map((step, index, all) => buildStep(step, index, all));

state.authorization = {
  mode: "preapproved",
  usecase_ref: ref,
  version: usecase.version
};

return [{ json: state }];

const state = items[0].json;

state.llm = {
